 if(opts)return `<select class="fin" data-sla-cr="${id}|v" aria-label="Value">${["",...opts].map(o=>`<option value="${E(o)}" ${String(row.v)===o?"selected":""}>${o===""?"Choose a value":E(o)}</option>`).join("")}</select>`;
 if(ty==="boolean")return `<select class="fin" data-sla-cr="${id}|v" aria-label="Value"><option value="true" ${String(row.v)==="true"?"selected":""}>Yes</option><option value="false" ${String(row.v)==="false"?"selected":""}>No</option></select>`;
