function phaseCard(ag,p){const [k,lab,help,req]=p;const ph=ag.cond[k]||{m:"all",rows:[]};const fl=DATAMODEL.fields(ag.tbl);
 const rows=ph.rows.map((r,i)=>{const f=fieldDef(ag.tbl,r.f);const ty=f?FTYPE(f.type):"string";return `<div class="sla-cr"><select class="fin" data-sla-cr="${k}|${i}|f" aria-label="Field">${fl.map(x=>`<option value="${E(x.k)}" ${x.k===r.f?"selected":""}>${E(x.label)}</option>`).join("")}${f?"":`<option value="${E(r.f)}" selected>${E(r.f)} (not on this table)</option>`}</select><select class="fin" data-sla-cr="${k}|${i}|op" aria-label="Operator">${opsFor(ty).map(o=>`<option ${o===r.op?"selected":""}>${o}</option>`).join("")}</select><div class="sla-cv">${valInput(ag.tbl,k,i,r)}</div><button class="btn quiet" data-sla-cdel="${k}|${i}" aria-label="Remove this condition">Remove</button></div>`}).join("");
 return `<div class="sla-ph ${req&&!ph.rows.length&&ag.kind!=="score"?"need":""}"><div class="row sp"><b>${lab}${req?` <small class="muted">required</small>`:""}</b>${ph.rows.length>1?`<span class="sla-seg" role="group" aria-label="Match mode"><button type="button" class="${ph.m==="all"?"on":""}" data-sla-cmode="${k}|all">All</button><button type="button" class="${ph.m==="any"?"on":""}" data-sla-cmode="${k}|any">Any</button></span>`:""}</div><p class="muted small">${help}</p>${rows||`<p class="muted small">${req?"Add at least one condition.":"Not set."}</p>`}<div class="row" style="margin-top:8px"><button class="btn quiet" data-sla-cadd="${k}">Add a condition</button></div><p class="sla-sum small" data-role="story">${E(phaseText(ag.tbl,ph))}</p></div>`}
const tg=(path,val,cur,label)=>`<button type="button" class="chip ${cur.includes(val)?"on":""}" aria-pressed="${cur.includes(val)}" data-sla-tg="${path}|${E(val)}">${E(label||val)}</button>`;
const fin=(path,val,type,extra)=>`<input class="fin" type="${type||"text"}" data-sla-f="${path}" value="${E(val==null?"":val)}" ${extra||""}>`;
const fsel=(path,val,opts,extra)=>`<select class="fin" data-sla-f="${path}" ${extra||""}>${opts.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${E(v)}" ${String(v)===String(val)?"selected":""}>${E(l)}</option>`}).join("")}</select>`;
