 const sch=card("Schedule","The calendar the clock follows: only hours inside it count.",`<div class="sla-fg">${field("Calendar",fsel("sch.cal",ag.sch.cal,SCH.map(s=>[s.id,s.n])),"",1)}${field("Time zone",fsel("sch.tz",ag.sch.tz,Object.keys(TZS)),"The zone the calendar hours are in.")}${field("Time zone source",fsel("sch.src",ag.sch.src||"Fixed",["Fixed","Caller's location","Assignment group's location"]),"Prototype measures with the fixed zone.")}${field("Holidays",fsel("sch.hol",ag.sch.hol||"us",Object.entries(HOLSETS)),"Holidays do not count as working time.")}</div><div class="sla-wk" role="img" aria-label="Open hours by day of week">${wkstrip}</div><p class="muted small">${hrsDay} schedule hours per working day. Shaded bars show the open hours of each day in ${E(ag.sch.tz)} time.</p>`);
